BEGIN;
CREATE SCHEMA erp_sales_requisition_private;
REVOKE ALL ON SCHEMA erp_sales_requisition_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_sales_requisitions(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),invoice_id uuid NOT NULL,warehouse_id uuid NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),UNIQUE(cafe_id,invoice_id),FOREIGN KEY(cafe_id,invoice_id)REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,warehouse_id)REFERENCES public.bf_warehouses(cafe_id,id));
CREATE TABLE public.erp_sales_requisition_lines(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,request_id uuid NOT NULL,item_id uuid NOT NULL,quantity numeric(16,3)NOT NULL CHECK(quantity>0),delivered numeric(16,3)NOT NULL DEFAULT 0 CHECK(delivered>=0),cancelled numeric(16,3)NOT NULL DEFAULT 0 CHECK(cancelled>=0),unit_name text NOT NULL,factor numeric NOT NULL CHECK(factor>0),net numeric(16,2)NOT NULL,allow_below_cost boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,request_id)REFERENCES public.erp_sales_requisitions(cafe_id,id),FOREIGN KEY(cafe_id,id)REFERENCES public.bf_document_lines(cafe_id,id)DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(cafe_id,item_id)REFERENCES public.bf_items(cafe_id,id),CHECK(delivered+cancelled<=quantity));
CREATE TABLE public.erp_sales_requisition_releases(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,request_line_id uuid NOT NULL,document_id uuid NOT NULL,line_id uuid NOT NULL,component_id uuid NOT NULL,quantity numeric(16,3)NOT NULL CHECK(quantity>0),cost numeric(16,2)NOT NULL CHECK(cost>=0),return_reserved numeric(16,3)NOT NULL DEFAULT 0 CHECK(return_reserved>=0 AND return_reserved<=quantity),effective_on date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,request_line_id)REFERENCES public.erp_sales_requisition_lines(cafe_id,id),FOREIGN KEY(cafe_id,document_id)REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,line_id)REFERENCES public.bf_document_lines(cafe_id,id),FOREIGN KEY(component_id)REFERENCES public.bf_line_components(id));
CREATE TABLE public.erp_sales_requisition_returns(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,request_id uuid NOT NULL,refund_id uuid NOT NULL,refund_line_id uuid NOT NULL,source_line_id uuid NOT NULL,financial_quantity numeric(16,3)NOT NULL CHECK(financial_quantity>0),cancelled_quantity numeric(16,3)NOT NULL CHECK(cancelled_quantity>=0),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),UNIQUE(cafe_id,refund_line_id),FOREIGN KEY(cafe_id,request_id)REFERENCES public.erp_sales_requisitions(cafe_id,id),FOREIGN KEY(cafe_id,refund_id)REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,refund_line_id)REFERENCES public.bf_document_lines(cafe_id,id)DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(cafe_id,source_line_id)REFERENCES public.erp_sales_requisition_lines(cafe_id,id));
CREATE TABLE public.erp_sales_requisition_return_lines(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,return_id uuid NOT NULL,release_id uuid NOT NULL,quantity numeric(16,3)NOT NULL CHECK(quantity>0),cost numeric(16,2)NOT NULL CHECK(cost>=0),received numeric(16,3)NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity),received_cost numeric(16,2)NOT NULL DEFAULT 0 CHECK(received_cost>=0 AND received_cost<=cost),UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,return_id)REFERENCES public.erp_sales_requisition_returns(cafe_id,id),FOREIGN KEY(cafe_id,release_id)REFERENCES public.erp_sales_requisition_releases(cafe_id,id));
CREATE TABLE public.erp_sales_requisition_receipts(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,return_line_id uuid NOT NULL,document_id uuid NOT NULL,quantity numeric(16,3)NOT NULL CHECK(quantity>0),cost numeric(16,2)NOT NULL CHECK(cost>=0),effective_on date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(cafe_id,return_line_id)REFERENCES public.erp_sales_requisition_return_lines(cafe_id,id),FOREIGN KEY(cafe_id,document_id)REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_sales_requisition_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL,request_id uuid NOT NULL,action text NOT NULL,payload jsonb NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(cafe_id,request_id)REFERENCES public.erp_sales_requisitions(cafe_id,id));
CREATE TABLE erp_sales_requisition_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE INDEX erp_sales_requisition_lines_request ON public.erp_sales_requisition_lines(cafe_id,request_id);
CREATE INDEX erp_sales_requisition_releases_line ON public.erp_sales_requisition_releases(cafe_id,request_line_id);
CREATE INDEX erp_sales_requisition_returns_request ON public.erp_sales_requisition_returns(cafe_id,request_id);
CREATE INDEX erp_sales_requisition_return_lines_parent ON public.erp_sales_requisition_return_lines(cafe_id,return_id);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_sales_requisitions','erp_sales_requisition_lines','erp_sales_requisition_releases','erp_sales_requisition_returns','erp_sales_requisition_return_lines','erp_sales_requisition_receipts','erp_sales_requisition_events']LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END$$;
CREATE FUNCTION erp_sales_requisition_private.branch_allowed(c uuid,r jsonb)RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE allowed boolean;BEGIN IF to_regprocedure('erp_branch_private.row_allowed(uuid,uuid,jsonb,text)')IS NULL THEN RETURN true;END IF;EXECUTE 'SELECT erp_branch_private.row_allowed($1,erp_branch_private.current_branch($1),$2,'''')'INTO allowed USING c,r;RETURN coalesce(allowed,false);END$$;
CREATE FUNCTION erp_sales_requisition_private.can_read(c uuid,i uuid)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$SELECT EXISTS(SELECT 1 FROM public.erp_sales_requisitions r JOIN public.bf_documents d ON d.cafe_id=r.cafe_id AND d.id=r.invoice_id WHERE r.cafe_id=c AND r.id=i AND erp_inventory_private.warehouse_allowed(c,r.warehouse_id,'read')AND erp_sales_requisition_private.branch_allowed(c,jsonb_build_object('id',d.id,'customerId',d.party_id)))$$;
CREATE FUNCTION erp_sales_requisition_private.capture(n public.bf_document_lines)RETURNS public.bf_document_lines LANGUAGE plpgsql SET search_path=''AS $$DECLARE d public.bf_documents;source public.erp_sales_requisition_lines;release public.erp_sales_requisition_releases;amount numeric;unfulfilled numeric;cancelled numeric;remaining numeric;take numeric;cost numeric;rid uuid:=gen_random_uuid();BEGIN
 SELECT * INTO STRICT d FROM public.bf_documents WHERE cafe_id=n.cafe_id AND id=n.document_id;PERFORM pg_advisory_xact_lock(hashtextextended(n.cafe_id::text,60412));
 IF d.kind='sale' THEN
  IF n.inventory_item_id IS NULL OR n.activity_kind='service' OR d.shift_id IS NOT NULL OR d.paid>=d.total OR NOT EXISTS(SELECT 1 FROM public.erp_inventory_settings WHERE cafe_id=n.cafe_id AND payload->'salesRequisitions'='true'::jsonb)THEN RETURN n;END IF;
  IF NOT EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=n.cafe_id AND item_id=n.inventory_item_id AND kind='product'AND status='active')OR NOT erp_inventory_private.sale_warehouse_allowed(n.cafe_id,d.warehouse_id,d.created_by)THEN RAISE EXCEPTION 'الصنف أو المستودع غير متاح لإذن المبيعات' USING ERRCODE='42501';END IF;
  IF erp_inventory_private.unit_factor(n.cafe_id,n.inventory_item_id,n.unit_label)IS DISTINCT FROM n.stock_unit_factor THEN RAISE EXCEPTION 'تحويل وحدة السطر تغير';END IF;
  amount:=n.quantity*n.stock_unit_factor;IF amount<=0 OR amount>1000000 OR amount<>round(amount,3)THEN RAISE EXCEPTION 'كمية إذن الصرف غير صالحة';END IF;
  INSERT INTO public.erp_sales_requisitions(id,cafe_id,invoice_id,warehouse_id)VALUES(d.id,n.cafe_id,d.id,d.warehouse_id)ON CONFLICT(id)DO NOTHING;
  INSERT INTO public.erp_sales_requisition_lines(id,cafe_id,request_id,item_id,quantity,unit_name,factor,net,allow_below_cost)VALUES(n.id,n.cafe_id,d.id,n.inventory_item_id,amount,coalesce(n.unit_label,''),n.stock_unit_factor,n.net,coalesce((brand_finance_private.invoice_settings(n.cafe_id)->>'allowBelowCost')::boolean,false));
  n.item_id:=NULL;n.cost:=0;n.allocated_cost:=0;n.cost_status:='unknown';RETURN n;
 END IF;
 SELECT * INTO source FROM public.erp_sales_requisition_lines WHERE cafe_id=n.cafe_id AND id=n.reference_line_id FOR UPDATE;IF d.kind<>'refund'OR source.id IS NULL THEN RETURN n;END IF;
 amount:=n.quantity*source.factor;unfulfilled:=source.quantity-source.delivered-source.cancelled;cancelled:=least(amount,unfulfilled);remaining:=amount-cancelled;
 IF amount<=0 OR amount<>round(amount,3)OR amount>source.quantity THEN RAISE EXCEPTION 'كمية مرتجع إذن المبيعات غير صالحة';END IF;
 INSERT INTO public.erp_sales_requisition_returns(id,cafe_id,request_id,refund_id,refund_line_id,source_line_id,financial_quantity,cancelled_quantity)VALUES(rid,n.cafe_id,source.request_id,d.id,n.id,source.id,amount,cancelled);
 UPDATE public.erp_sales_requisition_lines SET cancelled=source.cancelled+least(amount,unfulfilled) WHERE id=source.id;
 FOR release IN SELECT * FROM public.erp_sales_requisition_releases WHERE cafe_id=n.cafe_id AND request_line_id=source.id AND return_reserved<quantity ORDER BY created_at,id FOR UPDATE LOOP
  take:=least(remaining,release.quantity-release.return_reserved);EXIT WHEN take<=0;cost:=round(release.cost*(release.return_reserved+take)/release.quantity,2)-coalesce((SELECT sum(x.cost)FROM public.erp_sales_requisition_return_lines x WHERE x.cafe_id=n.cafe_id AND x.release_id=release.id),0);
  INSERT INTO public.erp_sales_requisition_return_lines(id,cafe_id,return_id,release_id,quantity,cost)VALUES(gen_random_uuid(),n.cafe_id,rid,release.id,take,cost);UPDATE public.erp_sales_requisition_releases SET return_reserved=return_reserved+take WHERE id=release.id;remaining:=remaining-take;EXIT WHEN remaining=0;
 END LOOP;
 IF remaining<>0 THEN RAISE EXCEPTION 'المرتجع يتجاوز الكمية المسلمة المتاحة';END IF;
 UPDATE public.erp_sales_requisitions SET revision=revision+1 WHERE id=source.request_id;
 n.inventory_item_id:=source.item_id;n.item_id:=NULL;n.unit_label:=source.unit_name;n.stock_unit_factor:=source.factor;n.cost:=0;n.allocated_cost:=0;n.cost_status:=CASE WHEN amount>cancelled THEN 'unknown' ELSE 'known'END;RETURN n;
END$$;
CREATE FUNCTION erp_sales_requisition_private.handles(n public.bf_document_lines)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$SELECT EXISTS(SELECT 1 FROM public.erp_sales_requisition_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=n.document_id AND d.kind='refund'WHERE l.cafe_id=n.cafe_id AND l.id=n.reference_line_id)OR(n.inventory_item_id IS NOT NULL AND n.activity_kind<>'service'AND EXISTS(SELECT 1 FROM public.bf_documents d JOIN public.erp_inventory_settings s ON s.cafe_id=d.cafe_id WHERE d.cafe_id=n.cafe_id AND d.id=n.document_id AND d.kind='sale'AND d.shift_id IS NULL AND d.paid<d.total AND s.payload->'salesRequisitions'='true'::jsonb))$$;
DO $$DECLARE source text;target regprocedure;needle text;BEGIN
 source:=pg_get_functiondef('brand_finance_private.inventory_line_components()'::regprocedure);needle:=' IF NEW.reference_line_id IS NOT NULL THEN SELECT inventory_item_id';IF position(needle IN source)=0 THEN RAISE EXCEPTION 'Review inventory line hook before deferred sales';END IF;EXECUTE replace(source,needle,' IF erp_sales_requisition_private.handles(NEW)THEN RETURN erp_sales_requisition_private.capture(NEW);END IF;'||chr(10)||needle);
 FOREACH target IN ARRAY ARRAY['brand_finance_private.issue_company_invoice_actor(uuid,boolean,uuid,uuid,integer,numeric,uuid,text)'::regprocedure,'brand_finance_private.issue_manual_invoice_shipping_actor(uuid,boolean,uuid,uuid,integer,numeric,uuid,text)'::regprocedure]LOOP
  source:=pg_get_functiondef(target);needle:='IF line_cost_status IS DISTINCT FROM ''known'' THEN';IF position(needle IN source)=0 THEN RAISE EXCEPTION 'Review issuer known-cost check for %',target;END IF;
  EXECUTE replace(source,needle,'IF line_cost_status IS DISTINCT FROM ''known'' AND NOT EXISTS(SELECT 1 FROM public.erp_sales_requisition_lines pending WHERE pending.cafe_id=p_cafe_id AND pending.id=line_id) THEN');
 END LOOP;
END$$;
CREATE FUNCTION erp_sales_requisition_private.document(c uuid,k text,source uuid,w uuid,d date,note text)RETURNS uuid LANGUAGE plpgsql SET search_path=''AS $$DECLARE i uuid:=gen_random_uuid();BEGIN IF d IS NULL OR d>(now()AT TIME ZONE'Asia/Riyadh')::date THEN RAISE EXCEPTION 'حدد تاريخ الحركة الفعلية دون تاريخ مستقبلي';END IF;PERFORM erp_inventory_private.assert_open(c,d);INSERT INTO public.bf_documents(id,cafe_id,kind,total,paid,warehouse_id,reference_id,note,created_by,created_at)VALUES(i,c,k,0,0,w,source,left(note,1000),auth.uid(),(d+time'12:00')AT TIME ZONE'Asia/Riyadh');RETURN i;END$$;
CREATE FUNCTION erp_sales_requisition_private.deliver(c uuid,p jsonb)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$DECLARE request public.erp_sales_requisitions;l public.erp_sales_requisition_lines;stock public.bf_stock;row jsonb;qty numeric;actual numeric;doc uuid;line uuid;component uuid;released jsonb:='[]';d date:=(p->>'date')::date;BEGIN
 SELECT * INTO request FROM public.erp_sales_requisitions WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF request.id IS NULL OR NOT erp_sales_requisition_private.can_read(c,request.id)OR NOT erp_inventory_private.warehouse_allowed(c,request.warehouse_id,'write')THEN RAISE EXCEPTION 'إذن الصرف غير متاح في هذا المستودع' USING ERRCODE='42501';END IF;IF request.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'إذن الصرف تغير' USING ERRCODE='40001';END IF;
 IF d<(SELECT(created_at AT TIME ZONE'Asia/Riyadh')::date FROM public.bf_documents WHERE id=request.invoice_id)OR d<coalesce((SELECT max(effective_on)FROM public.erp_sales_requisition_releases r JOIN public.erp_sales_requisition_lines x ON x.id=r.request_line_id WHERE x.request_id=request.id),d)THEN RAISE EXCEPTION 'تاريخ التسليم يسبق المستند أو حركة سابقة';END IF;
 IF jsonb_typeof(p->'lines')IS DISTINCT FROM'array' OR jsonb_array_length(p->'lines')NOT BETWEEN 1 AND 100 OR(SELECT count(DISTINCT x->>'id')FROM jsonb_array_elements(p->'lines')x)<>jsonb_array_length(p->'lines')THEN RAISE EXCEPTION 'حدد بنود إذن الصرف دون تكرار';END IF;
 doc:=erp_sales_requisition_private.document(c,'stock_adjust',request.invoice_id,request.warehouse_id,d,'صرف مبيعات مؤجل '||coalesce(p->>'note',''));
 FOR row IN SELECT value FROM jsonb_array_elements(p->'lines')LOOP
  SELECT * INTO l FROM public.erp_sales_requisition_lines WHERE cafe_id=c AND request_id=request.id AND id=(row->>'id')::uuid FOR UPDATE;qty:=(row->>'quantity')::numeric;
  IF l.id IS NULL OR qty IS NULL OR qty<=0 OR qty<>round(qty,3)OR qty>l.quantity-l.delivered-l.cancelled THEN RAISE EXCEPTION 'راجع الكمية المتبقية للتسليم';END IF;
  SELECT * INTO stock FROM public.bf_stock WHERE cafe_id=c AND item_id=l.item_id AND warehouse_id=request.warehouse_id FOR UPDATE;IF stock.item_id IS NULL OR NOT coalesce(stock.cost_known,false)OR stock.quantity<qty THEN RAISE EXCEPTION 'الكمية المتوفرة أو التكلفة المثبتة لا تكفي للتسليم';END IF;
  PERFORM erp_inventory_private.stage_tracking(c,doc,l.item_id,request.warehouse_id,-qty,coalesce(row->'tracking','[]'));actual:=brand_finance_private.stock_move(c,doc,l.item_id,request.warehouse_id,-qty,0);
  IF NOT l.allow_below_cost AND round(l.net*qty/l.quantity,2)<actual THEN RAISE EXCEPTION 'سعر السطر أقل من تكلفة الكمية المسلمة';END IF;
  line:=gen_random_uuid();component:=gen_random_uuid();INSERT INTO public.bf_document_lines(id,cafe_id,document_id,item_id,name,quantity,unit_price,net,tax,cost,cost_status,allocated_cost,unit_label,stock_unit_factor)VALUES(line,c,doc,l.item_id,(SELECT name FROM public.bf_items WHERE id=l.item_id),qty,0,0,0,actual,'known',actual,l.unit_name,1);
  INSERT INTO public.bf_line_components(id,cafe_id,line_id,item_id,warehouse_id,quantity,cost,allocated_cost,cost_mode,allocation_divisor,cost_status)VALUES(component,c,line,l.item_id,request.warehouse_id,qty,actual,actual,'full',1,'known');
  INSERT INTO public.erp_sales_requisition_releases(id,cafe_id,request_line_id,document_id,line_id,component_id,quantity,cost,effective_on)VALUES(gen_random_uuid(),c,l.id,doc,line,component,qty,actual,d);
  UPDATE public.erp_sales_requisition_lines SET delivered=delivered+qty WHERE id=l.id;PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5000'),actual,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1200'),0,actual);released:=released||jsonb_build_array(jsonb_build_object('id',l.id,'quantity',qty,'cost',actual));
 END LOOP;UPDATE public.erp_sales_requisitions SET revision=revision+1 WHERE id=request.id;
 INSERT INTO public.erp_sales_requisition_events(cafe_id,request_id,action,payload,actor)VALUES(c,request.id,'deliver',jsonb_build_object('documentId',doc,'date',d,'lines',released,'note',p->>'note'),auth.uid());RETURN jsonb_build_object('id',request.id,'documentId',doc);
END$$;
CREATE FUNCTION erp_sales_requisition_private.receive_return(c uuid,p jsonb)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$DECLARE ret public.erp_sales_requisition_returns;request public.erp_sales_requisitions;l public.erp_sales_requisition_return_lines;release public.erp_sales_requisition_releases;source public.erp_sales_requisition_lines;row jsonb;qty numeric;cost numeric;actual numeric;doc uuid;line uuid;docs jsonb:='[]';d date:=(p->>'date')::date;BEGIN
 SELECT * INTO ret FROM public.erp_sales_requisition_returns WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF ret.id IS NULL OR NOT erp_sales_requisition_private.can_read(c,ret.request_id)THEN RAISE EXCEPTION 'مرتجع إذن المبيعات غير متاح' USING ERRCODE='42501';END IF;IF ret.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'حالة استلام المرتجع تغيرت' USING ERRCODE='40001';END IF;SELECT * INTO STRICT request FROM public.erp_sales_requisitions WHERE cafe_id=c AND id=ret.request_id FOR UPDATE;
 IF NOT erp_inventory_private.warehouse_allowed(c,request.warehouse_id,'write')THEN RAISE EXCEPTION 'لا تملك صلاحية الاستلام في المستودع' USING ERRCODE='42501';END IF;
 IF d<(SELECT(created_at AT TIME ZONE'Asia/Riyadh')::date FROM public.bf_documents WHERE id=ret.refund_id)THEN RAISE EXCEPTION 'تاريخ الاستلام يسبق المرتجع';END IF;
 IF jsonb_typeof(p->'lines')IS DISTINCT FROM'array'OR jsonb_array_length(p->'lines')NOT BETWEEN 1 AND 100 OR(SELECT count(DISTINCT x->>'id')FROM jsonb_array_elements(p->'lines')x)<>jsonb_array_length(p->'lines')THEN RAISE EXCEPTION 'حدد بنود استلام المرتجع دون تكرار';END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(p->'lines')LOOP SELECT * INTO l FROM public.erp_sales_requisition_return_lines WHERE cafe_id=c AND return_id=ret.id AND id=(row->>'id')::uuid FOR UPDATE;qty:=(row->>'quantity')::numeric;IF l.id IS NULL OR qty IS NULL OR qty<=0 OR qty<>round(qty,3)OR qty>l.quantity-l.received THEN RAISE EXCEPTION 'الاستلام يتجاوز الكمية المرتجعة المتبقية';END IF;
  SELECT * INTO STRICT release FROM public.erp_sales_requisition_releases WHERE cafe_id=c AND id=l.release_id;IF d<release.effective_on THEN RAISE EXCEPTION 'تاريخ الاستلام يسبق التسليم الأصلي';END IF;SELECT * INTO STRICT source FROM public.erp_sales_requisition_lines WHERE cafe_id=c AND id=release.request_line_id;cost:=round(l.cost*(l.received+qty)/l.quantity,2)-l.received_cost;
  doc:=erp_sales_requisition_private.document(c,'refund',release.document_id,request.warehouse_id,d,'استلام مرتجع مبيعات مؤجل '||coalesce(p->>'note',''));PERFORM erp_inventory_private.stage_tracking_return(c,doc,source.item_id,request.warehouse_id,qty,release.document_id);actual:=brand_finance_private.stock_move(c,doc,source.item_id,request.warehouse_id,qty,cost/qty);IF actual IS DISTINCT FROM cost THEN RAISE EXCEPTION 'تغيرت تكلفة استلام المرتجع';END IF;
  line:=gen_random_uuid();INSERT INTO public.bf_document_lines(id,cafe_id,document_id,item_id,name,quantity,unit_price,net,tax,cost,cost_status,allocated_cost,unit_label,stock_unit_factor)VALUES(line,c,doc,source.item_id,(SELECT name FROM public.bf_items WHERE id=source.item_id),qty,0,0,0,cost,'known',cost,source.unit_name,1);
  INSERT INTO public.bf_line_components(cafe_id,line_id,item_id,warehouse_id,quantity,cost,allocated_cost,cost_mode,allocation_divisor,cost_status,original_component_id)VALUES(c,line,source.item_id,request.warehouse_id,qty,cost,cost,'full',1,'known',release.component_id);
  PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1200'),cost,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5000'),0,cost);
  INSERT INTO public.erp_sales_requisition_receipts(id,cafe_id,return_line_id,document_id,quantity,cost,effective_on)VALUES(gen_random_uuid(),c,l.id,doc,qty,cost,d);UPDATE public.erp_sales_requisition_return_lines SET received=l.received+qty,received_cost=round(l.cost*(l.received+qty)/l.quantity,2) WHERE id=l.id;docs:=docs||to_jsonb(doc::text);
 END LOOP;UPDATE public.erp_sales_requisition_returns SET revision=revision+1 WHERE id=ret.id;UPDATE public.erp_sales_requisitions SET revision=revision+1 WHERE id=request.id;
 INSERT INTO public.erp_sales_requisition_events(cafe_id,request_id,action,payload,actor)VALUES(c,request.id,'receive_return',jsonb_build_object('returnId',ret.id,'documentIds',docs,'date',d,'note',p->>'note'),auth.uid());RETURN jsonb_build_object('id',ret.id,'documentIds',docs);
END$$;
CREATE FUNCTION public.erp_sales_requisitions_write(p_cafe_id uuid,p_action text,p_payload jsonb,p_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$DECLARE old erp_sales_requisition_private.requests;result jsonb;BEGIN
 PERFORM erp_inventory_private.authorize(p_cafe_id,'approve');IF p_action IS NULL OR p_action NOT IN('deliver','receive_return')OR p_request_id IS NULL OR jsonb_typeof(p_payload)IS DISTINCT FROM'object'OR octet_length(p_payload::text)>262144 OR length(coalesce(p_payload->>'note',''))>5000 THEN RAISE EXCEPTION 'بيانات إجراء الإذن غير صالحة';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO old FROM erp_sales_requisition_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;IF old.request_id IS NOT NULL THEN IF old.actor<>auth.uid()OR old.action<>p_action OR old.payload<>p_payload THEN RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات مختلفة';END IF;RETURN old.result;END IF;
 result:=CASE p_action WHEN'deliver'THEN erp_sales_requisition_private.deliver(p_cafe_id,p_payload)ELSE erp_sales_requisition_private.receive_return(p_cafe_id,p_payload)END;INSERT INTO erp_sales_requisition_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END$$;
CREATE FUNCTION public.erp_sales_requisitions_read(p_cafe_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$DECLARE c uuid:=p_cafe_id;r text;BEGIN r:=erp_inventory_private.authorize(c,'read');RETURN jsonb_build_object('canApprove',r IN('owner','manager','warehouse')AND erp_access_private.allowed(c,'inventory','approve'),
 'requests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',q.id,'revision',q.revision,'invoiceId',q.invoice_id,'number',d.number,'customer',coalesce(p.name,''),'warehouseId',q.warehouse_id,'warehouse',w.name,'date',(d.created_at AT TIME ZONE'Asia/Riyadh')::date,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'itemId',l.item_id,'name',i.name,'quantity',l.quantity,'delivered',l.delivered,'cancelled',l.cancelled,'pending',l.quantity-l.delivered-l.cancelled,'unit',i.unit,'saleUnit',l.unit_name,'factor',l.factor,'trackingMode',coalesce(m.tracking_mode,'quantity'))ORDER BY l.created_at,l.id)FROM public.erp_sales_requisition_lines l JOIN public.bf_items i ON i.cafe_id=c AND i.id=l.item_id LEFT JOIN public.erp_inventory_items m ON m.cafe_id=c AND m.item_id=l.item_id WHERE l.cafe_id=c AND l.request_id=q.id),'[]'))ORDER BY q.created_at DESC)FROM public.erp_sales_requisitions q JOIN public.bf_documents d ON d.cafe_id=c AND d.id=q.invoice_id JOIN public.bf_warehouses w ON w.cafe_id=c AND w.id=q.warehouse_id LEFT JOIN public.bf_parties p ON p.cafe_id=c AND p.id=d.party_id WHERE q.cafe_id=c AND erp_sales_requisition_private.can_read(c,q.id)),'[]'),
 'returns',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'revision',r.revision,'requestId',r.request_id,'refundId',r.refund_id,'number',d.number,'sourceLineId',r.source_line_id,'quantity',r.financial_quantity,'cancelled',r.cancelled_quantity,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'quantity',l.quantity,'received',l.received,'cost',l.cost,'releaseId',l.release_id,'name',i.name,'unit',i.unit)ORDER BY l.id)FROM public.erp_sales_requisition_return_lines l JOIN public.erp_sales_requisition_releases rel ON rel.cafe_id=c AND rel.id=l.release_id JOIN public.erp_sales_requisition_lines sl ON sl.cafe_id=c AND sl.id=rel.request_line_id JOIN public.bf_items i ON i.cafe_id=c AND i.id=sl.item_id WHERE l.cafe_id=c AND l.return_id=r.id),'[]'))ORDER BY r.created_at DESC)FROM public.erp_sales_requisition_returns r JOIN public.bf_documents d ON d.cafe_id=c AND d.id=r.refund_id WHERE r.cafe_id=c AND erp_sales_requisition_private.can_read(c,r.request_id)),'[]'),
 'releases',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'sourceLineId',r.request_line_id,'documentId',r.document_id,'quantity',r.quantity,'cost',r.cost,'returnReserved',r.return_reserved,'date',r.effective_on)ORDER BY r.created_at DESC)FROM public.erp_sales_requisition_releases r JOIN public.erp_sales_requisition_lines l ON l.cafe_id=c AND l.id=r.request_line_id WHERE r.cafe_id=c AND erp_sales_requisition_private.can_read(c,l.request_id)),'[]'),
 'receipts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'returnLineId',x.return_line_id,'documentId',x.document_id,'quantity',x.quantity,'cost',x.cost,'date',x.effective_on)ORDER BY x.created_at DESC)FROM public.erp_sales_requisition_receipts x JOIN public.erp_sales_requisition_return_lines l ON l.cafe_id=c AND l.id=x.return_line_id JOIN public.erp_sales_requisition_returns r ON r.cafe_id=c AND r.id=l.return_id WHERE x.cafe_id=c AND erp_sales_requisition_private.can_read(c,r.request_id)),'[]'));
END$$;
CREATE FUNCTION erp_sales_requisition_private.cost_facts(c uuid,f date,t date)RETURNS SETOF jsonb LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT jsonb_build_object('id',r.id,'invoiceId',q.invoice_id,'sourceLineId',l.id,'financialDocumentId',q.invoice_id,'documentId',r.document_id,'kind','delivery','date',r.effective_on,'quantity',r.quantity,'cost',r.cost)FROM public.erp_sales_requisition_releases r JOIN public.erp_sales_requisition_lines l ON l.cafe_id=c AND l.id=r.request_line_id JOIN public.erp_sales_requisitions q ON q.cafe_id=c AND q.id=l.request_id WHERE r.cafe_id=c AND r.effective_on BETWEEN f AND t AND erp_sales_requisition_private.can_read(c,q.id)
 UNION ALL
 SELECT jsonb_build_object('id',r.id,'invoiceId',q.invoice_id,'sourceLineId',ret.source_line_id,'financialDocumentId',ret.refund_id,'documentId',r.document_id,'kind','return_receipt','date',r.effective_on,'quantity',-r.quantity,'cost',-r.cost)FROM public.erp_sales_requisition_receipts r JOIN public.erp_sales_requisition_return_lines l ON l.cafe_id=c AND l.id=r.return_line_id JOIN public.erp_sales_requisition_returns ret ON ret.cafe_id=c AND ret.id=l.return_id JOIN public.erp_sales_requisitions q ON q.cafe_id=c AND q.id=ret.request_id WHERE r.cafe_id=c AND r.effective_on BETWEEN f AND t AND erp_sales_requisition_private.can_read(c,q.id)
$$;
CREATE FUNCTION erp_sales_requisition_private.line_costs(c uuid,a date)RETURNS SETOF jsonb LANGUAGE sql STABLE SET search_path=''AS $$
 WITH quantities AS(SELECT l.id,l.request_id,l.item_id,l.quantity,
 coalesce((SELECT sum(r.quantity)FROM public.erp_sales_requisition_releases r WHERE r.cafe_id=c AND r.request_line_id=l.id AND r.effective_on<=a),0)delivered,
 coalesce((SELECT sum(r.cost)FROM public.erp_sales_requisition_releases r WHERE r.cafe_id=c AND r.request_line_id=l.id AND r.effective_on<=a),0)delivered_cost,
 coalesce((SELECT sum(r.cancelled_quantity)FROM public.erp_sales_requisition_returns r JOIN public.bf_documents d ON d.cafe_id=c AND d.id=r.refund_id WHERE r.cafe_id=c AND r.source_line_id=l.id AND(d.created_at AT TIME ZONE'Asia/Riyadh')::date<=a),0)cancelled,
 coalesce((SELECT sum(r.financial_quantity-r.cancelled_quantity)FROM public.erp_sales_requisition_returns r JOIN public.bf_documents d ON d.cafe_id=c AND d.id=r.refund_id WHERE r.cafe_id=c AND r.source_line_id=l.id AND(d.created_at AT TIME ZONE'Asia/Riyadh')::date<=a),0)return_expected,
 coalesce((SELECT sum(r.quantity)FROM public.erp_sales_requisition_receipts r JOIN public.erp_sales_requisition_return_lines x ON x.cafe_id=c AND x.id=r.return_line_id JOIN public.erp_sales_requisition_returns ret ON ret.cafe_id=c AND ret.id=x.return_id WHERE r.cafe_id=c AND ret.source_line_id=l.id AND r.effective_on<=a),0)returned,
 coalesce((SELECT sum(r.cost)FROM public.erp_sales_requisition_receipts r JOIN public.erp_sales_requisition_return_lines x ON x.cafe_id=c AND x.id=r.return_line_id JOIN public.erp_sales_requisition_returns ret ON ret.cafe_id=c AND ret.id=x.return_id WHERE r.cafe_id=c AND ret.source_line_id=l.id AND r.effective_on<=a),0)returned_cost
 FROM public.erp_sales_requisition_lines l JOIN public.erp_sales_requisitions q ON q.cafe_id=c AND q.id=l.request_id JOIN public.bf_documents d ON d.cafe_id=c AND d.id=q.invoice_id WHERE l.cafe_id=c AND(d.created_at AT TIME ZONE'Asia/Riyadh')::date<=a AND erp_sales_requisition_private.can_read(c,q.id))
 SELECT jsonb_build_object('invoiceId',request_id,'sourceLineId',id,'itemId',item_id,'deliveredQuantity',delivered,'cancelledQuantity',cancelled,'returnedQuantity',returned,'pendingQuantity',quantity-delivered-cancelled,'returnPendingQuantity',return_expected-returned,'deliveredCost',delivered_cost,'returnedCost',returned_cost,'netCost',delivered_cost-returned_cost,'complete',quantity-delivered-cancelled=0 AND return_expected-returned=0)FROM quantities
$$;
DO $$DECLARE source text;needle text:='d.kind IN(''refund'',''journal'')';BEGIN
 IF to_regprocedure('erp_reports_private.linked_documents(uuid,jsonb,uuid)')IS NOT NULL THEN
 source:=pg_get_functiondef('erp_reports_private.linked_documents(uuid,jsonb,uuid)'::regprocedure);IF position(needle IN source)=0 THEN RAISE EXCEPTION 'Review linked operational document report before deferred COGS integration';END IF;
 EXECUTE replace(source,needle,'(d.kind IN(''refund'',''journal'')OR EXISTS(SELECT 1 FROM public.erp_sales_requisition_releases release WHERE release.cafe_id=c AND release.document_id=d.id))');END IF;
END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_sales_requisition_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_sales_requisitions_read(uuid),public.erp_sales_requisitions_write(uuid,text,jsonb,uuid)FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_sales_requisitions_read(uuid),public.erp_sales_requisitions_write(uuid,text,jsonb,uuid)TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
